<?php
/**
 * Авторские права Андриянов Н.Г.
 */
if (!defined('ABSPATH')) exit;
class OAI_Admin {
 public static function ensure_token(){
  if(!get_option('oai_bearer_token','')){
   $old=get_option('oai_api_token','');
   update_option('oai_bearer_token',$old?:wp_generate_password(48,false,false),false);
  }
  if(!get_option('oai_bearer_user_id',0)){
   $license=OAI_License::status();
   $uid=absint($license['owner_user_id']??0);
   if($uid && user_can($uid,'manage_options')) update_option('oai_bearer_user_id',$uid,false);
  }
 }
 public static function menu(){add_menu_page('AI Admin','AI Admin','manage_options','okean-ai-admin',array(__CLASS__,'page'),'dashicons-admin-generic',58);}
 public static function page(){
  $agent_new='';
  if(isset($_POST['oai_regen']) && check_admin_referer('oai_regen')){update_option('oai_bearer_token',wp_generate_password(48,false,false),false);echo '<div class="notice notice-success"><p>Токен перевыпущен.</p></div>';}
  if(isset($_POST['oai_local_license_activate']) && check_admin_referer('oai_local_license')){ $ls=OAI_License::activate_local_owner(); if(is_wp_error($ls)) echo '<div class="notice notice-error"><p>'.esc_html($ls->get_error_message()).'</p></div>'; else echo '<div class="notice notice-success"><p>Local Owner License активирована для текущего администратора. MCP теперь доступен без внешней подписки.</p></div>'; }
  if(isset($_POST['oai_local_license_deactivate']) && check_admin_referer('oai_local_license')){ OAI_License::deactivate_local_owner(); echo '<div class="notice notice-warning"><p>Local Owner License отключена.</p></div>'; }
  if(isset($_POST['oai_agent_generate']) && check_admin_referer('oai_agent')){ $agent_new=OAI_Agent::generate_key(); echo '<div class="notice notice-success"><p>Новый удалённый Agent Key создан. Скопируйте его сейчас: он больше не показывается.</p></div>'; }
  if(isset($_POST['oai_agent_disable']) && check_admin_referer('oai_agent')){ OAI_Agent::disable(); echo '<div class="notice notice-warning"><p>Удалённый Agent Channel отключён.</p></div>'; }
  if(isset($_POST['oai_agent_scopes']) && check_admin_referer('oai_agent_scopes')){ $scopes=isset($_POST['oai_scopes'])?(array)$_POST['oai_scopes']:array(); OAI_Agent::set_scopes($scopes); echo '<div class="notice notice-success"><p>Права удалённого канала обновлены.</p></div>'; }
  $token=self::ensure_token()?:get_option('oai_bearer_token'); $rows=OAI_DB::all(); $agent_scopes=OAI_Agent::scopes(); ?>
<div class="wrap"><h1>AI Admin <small>v<?php echo esc_html(OAI_VERSION);?></small></h1>
<div class="card" style="max-width:900px;padding:20px"><h2>Авторизация AI Admin</h2><p>Для внешних клиентов можно использовать стандартный WordPress Application Password. Он создаётся в профиле администратора WordPress и передаётся по HTTPS как HTTP Basic: <code>логин:пароль приложения</code>. AI Admin также сохраняет собственный Bearer-токен для совместимости.</p><p><strong>Проверка:</strong> <code>GET <?php echo esc_html(rest_url('okean-ai/v1/auth/status'));?></code></p><p>Application Password не является обычным паролем WordPress и не должен передаваться в чат. Создайте отдельный пароль приложения для AI Admin и при необходимости отзывайте его в профиле пользователя.</p></div><div class="card" style="max-width:900px;padding:20px"><h2>Защищённый API</h2><p>AI не записывает данные напрямую. Операция сначала попадает в песочницу, затем требует подтверждения и только после этого применяется.</p><p><strong>REST:</strong> <code><?php echo esc_html(rest_url('okean-ai/v1/'));?></code></p><p><strong>Bearer-токен:</strong></p><code style="display:block;padding:10px;background:#f6f7f7">Bearer <?php echo esc_html($token);?></code><form method="post" style="margin-top:12px"><?php wp_nonce_field('oai_regen');?><button name="oai_regen" class="button">Перевыпустить токен</button></form></div>
<div class="card" style="max-width:900px;padding:20px;margin-top:18px"><h2>Local Owner License</h2><p>Локальная лицензия владельца сайта для собственного AI Admin. Не требует внешней подписки и не отключает sandbox, HMAC или ручное подтверждение.</p><p><strong>Состояние:</strong> <?php $ls=OAI_License::status(); echo $ls['active']?'активна':'не активна'; ?> <strong>План:</strong> <?php echo esc_html($ls['plan']); ?> <strong>Site ID:</strong> <code><?php echo esc_html($ls['site_id']); ?></code></p><form method="post"><?php wp_nonce_field('oai_local_license'); ?><button name="oai_local_license_activate" class="button button-primary">Активировать Local Owner License</button> <button name="oai_local_license_deactivate" class="button">Отключить</button></form></div>
<div class="card" style="max-width:900px;padding:20px;margin-top:18px"><h2>Безопасный удалённый канал для AI Agent</h2><p>Это отдельный канал, не дающий произвольного доступа к WordPress. Запросы принимаются только по HMAC-SHA256, защищены от повторной отправки и проходят через явный список разрешённых действий.</p><p><strong>Endpoint:</strong> <code><?php echo esc_html(rest_url('okean-ai/v1/agent/'));?></code></p><p><strong>Состояние:</strong> <?php echo OAI_Agent::enabled()?'включён':'выключен';?></p>
<?php if($agent_new):?><p><strong>Agent Key (показан один раз):</strong></p><code style="display:block;padding:10px;background:#fff4cc;word-break:break-all"><?php echo esc_html($agent_new);?></code><?php endif;?>
<form method="post" style="margin-top:12px"><?php wp_nonce_field('oai_agent');?><button name="oai_agent_generate" class="button button-primary">Создать / перевыпустить Agent Key</button> <button name="oai_agent_disable" class="button">Отключить канал</button></form>
<form method="post" style="margin-top:16px"><h3>Разрешения канала</h3><?php wp_nonce_field('oai_agent_scopes'); foreach(array('read'=>'Чтение','sandbox'=>'Песочница','preview'=>'Preview','verify'=>'Проверка','approve'=>'Approve','apply'=>'Apply','rollback'=>'Rollback') as $k=>$label):?><label style="display:inline-block;margin:0 18px 8px 0"><input type="checkbox" name="oai_scopes[]" value="<?php echo esc_attr($k);?>" <?php checked(in_array($k,$agent_scopes,true));?>> <?php echo esc_html($label);?></label><?php endforeach;?><br><button name="oai_agent_scopes" class="button">Сохранить права</button></form></div>
<div class="card" style="max-width:900px;padding:20px;margin-top:18px"><h2>Workspace / Draft Theme</h2><p>AI Admin 1.6 introduces an isolated workspace that clones the active theme into a private draft area. Edits made there do not touch the live theme until an approved operation is applied.</p><p><strong>Workspace:</strong> <code><?php echo esc_html(get_option('oai_active_workspace','не создан'));?></code></p><p><strong>Surfaces:</strong> theme files, design tokens, page fields, Elementor, WooCommerce, Gutenberg, menus and options.</p><p><strong>Starter Theme:</strong> <code>starter-themes/classic</code> is bundled with the plugin.</p></div>
<h2>Sandbox / Audit</h2><table class="widefat striped"><thead><tr><th>ID</th><th>Operation</th><th>Status</th><th>Type</th><th>Target</th><th>Risk</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo (int)$r['id'];?></td><td><?php echo esc_html($r['operation_id']);?></td><td><?php echo esc_html($r['status']);?></td><td><?php echo esc_html($r['type']);?></td><td><?php echo esc_html($r['target']);?></td><td><?php echo esc_html($r['risk']);?></td><td><?php echo esc_html($r['created_at']);?><?php if(in_array($r['type'],array('post_content','elementor_widget_html','elementor_page_create'),true) && in_array($r['status'],array('pending','approved'),true)): $exp=time()+3600; $pt=OAI_REST::preview_token((int)$r['id'],$exp); $pl=add_query_arg(array('expires'=>$exp,'preview_token'=>$pt),rest_url('okean-ai/v1/preview/'.(int)$r['id']));?> <a target="_blank" href="<?php echo esc_url($pl);?>">Preview</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php }
}
